html,
body,
div,
span,
applet,
object,
iframe,
h1,
h2,
h3,
h4,
h5,
h6,
p,
blockquote,
pre,
a,
abbr,
acronym,
address,
big,
cite,
code,
del,
dfn,
em,
img,
ins,
kbd,
q,
s,
samp,
small,
strike,
strong,
sub,
sup,
tt,
var,
b,
u,
i,
center,
dl,
dt,
dd,
ol,
ul,
li,
fieldset,
form,
label,
legend,
table,
caption,
tbody,
tfoot,
thead,
tr,
th,
td,
article,
aside,
canvas,
details,
embed,
figure,
figcaption,
footer,
header,
hgroup,
menu,
nav,
output,
ruby,
section,
summary,
time,
mark,
audio,
video {
    border: 0;
    margin: 0;
    padding: 0;
    vertical-align: baseline
}

article,
aside,
details,
figcaption,
figure,
footer,
header,
hgroup,
menu,
nav,
section {
    display: block
}

ol,
ul {
    list-style: outside none none
}

blockquote,
q {
    quotes: none
}

blockquote::before,
blockquote::after,
q::before,
q::after {
    content: none
}

a {
    cursor: pointer;
    text-decoration: none!important;
    color: inherit
}

a.link {
    color: #3f94d5;
    font-weight: 600
}

button {
    cursor: pointer
}

table {
    text-align: left;
    border-collapse: collapse;
    border-spacing: 0
}

.clear {
    clear: both
}

a:hover {
    color: #f18121;
    transition: .3s
}

a.no_hover:hover {
    color: inherit
}

textarea:focus,
input:focus,
button:focus {
    outline: none
}

:focus {
    outline: none
}


@font-face {
    font-family: Quicksand;
    src: url(../fonts/quicksand-v8-vietnamese_latin-ext_latin-regular.eot);
    src: local("Quicksand Regular"), local("Quicksand-Regular"), url(../fonts/quicksand-v8-vietnamese_latin-ext_latin-regular.eot?#iefix) format("embedded-opentype"), url(../fonts/quicksand-v8-vietnamese_latin-ext_latin-regular.woff2) format("woff2"), url(../fonts/quicksand-v8-vietnamese_latin-ext_latin-regular.woff) format("woff"), url(../fonts/quicksand-v8-vietnamese_latin-ext_latin-regular.ttf) format("truetype"), url(../fonts/quicksand-v8-vietnamese_latin-ext_latin-regular.svg#Quicksand) format("svg");
    font-display: block
}


.breadcrumb {
    list-style: none;
    padding-bottom: 10px;
    padding-top: 10px;
}
.breadcrumb a {
    align-items: center;
    font-size: 13px;
    color: #424242;
}
.breadcrumb a span{
    font-size: 14px;
    font-weight: 600;
}
.breadcrumb a:hover {
    color: #363636
}

.breadcrumb li {
    display: inline;
    line-height: 23px;
}

.breadcrumb li+li:before {
    padding: 0 5px;
    color: black;
    content: "/\00a0";
}

.center h1 {
    font-size: 22px;
    font-weight: 600;
    color: #000;
    padding-bottom: 5px
}
.center .txt {
    line-height: 30px;
    color: #000;
    padding-bottom: 10px;
}
.open{
    display: block !important;
}
.text_list_hot{
    color: #ff2853;
    padding: 10px 0px;
}

.text_list_qq{
    color: #c39c11;
    padding: 10px 0px;
}

.text_list_update a, .text_list_update{
    color: #56ccf2 !important;
    font-size: 20px !important;
    font-weight: 600;
}
#info_tip{
    display:none;
    position:absolute;
    width:325px;
    border:1px solid #333;
    opacity:1;
    text-align:left;
    top:0;
    border-radius: 6px;
    background-color: #fff;
    box-shadow: 0 0 15px 0 rgba(0, 0, 0, .25);
    padding: 10px;
    z-index:9999!important
}
#info_tip .title-more {
    font-size: 13px;
    font-weight: 700;
    color: #f18121;
    letter-spacing: normal;
    margin-top: 0
}

#info_tip .title-more-other {
    font-weight: 500;
    letter-spacing: normal;
    color: #757575;
    line-height: 1;
    margin-top: 5px;
    margin-bottom: 10px
}

#info_tip .favorite {
    position: absolute;
    top: 10px;
    right: 15px
}

#info_tip .favorite i {
    color: #ff2853;
    font-size: 18px
}

#info_tip .info {
    font-size: 13px;
    font-weight: 500;
    line-height: 1.5;
    color: #000
}

#info_tip .list-tags {
    margin: 10px 0;
    font-size: 0
}

#info_tip .list-tags p {
    display: inline-block;
    border-radius: 5px;
    font-size: 12px;
