.tile {
    align-items: stretch;
    display: block;
    flex-basis: 0;
    flex-grow: 1;
    flex-shrink: 1;
    min-height: -webkit-min-content;
    min-height: -moz-min-content;
    min-height: min-content
}
.tile.is-ancestor {
    margin-left: -2px;
    margin-right: -2px;
    margin-top: -.75rem
}
.tile.is-ancestor:last-child {
    margin-bottom: -.75rem
}
.tile.is-ancestor:not(:last-child) {
    margin-bottom: .75rem
}
.tile.is-child {
    margin: 0!important
}
.tile.is-parent {
    padding: .75rem 2px
}
.tile.is-vertical {
    flex-direction: column
}
.tile.is-vertical>.tile.is-child:not(:last-child) {
    margin-bottom: 4px!important
}
.container:before{
    display: table;
    content: " ";
}
.hero {
    margin-bottom: 20px;
}
.hero {
    align-items: stretch;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}
.hero .tile.is-child>a {
    display: inline-block;
    width: 100%;
    height: 100%
}
.hero .tile .is-parent {
    max-height: 404px
}
.hero .hero-item {
    position: relative;
    min-height: 185px;
    height: 100%;
    overflow: hidden
}
.hero .hero-item:after {
    content: "";
    background-color: rgba(0, 0, 0, .65);
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    -webkit-transform: translateY(-100%);
    transform: translateY(-100%);
    transition: all .3s
}
.hero .hero-item.open:after {
    opacity: 1;
    visibility: visible;
    -webkit-transform: translateY(0);
    transform: translateY(0)
}
.hero .hero-item.open .cover {
    -webkit-filter: blur(2px);
    filter: blur(2px)
}
.hero .hero-item.open .captions {
    top: 25%;
    -webkit-transform: translateY(0);
    transform: translateY(0)
}
.hero .hero-item.open .captions h5 {
    font-size: 14px
}
.hero .hero-item.open .captions h3 {
    font-size: 20px
}
.hero .hero-item.open .chapter {
    top: 39%;
    left: 15px;
    -webkit-transform: translate(0);
    transform: translate(0)
}
.hero .hero-item.open .excerpt {
    opacity: 1;
    visibility: visible;
    -webkit-transform: translateY(0);
    transform: translateY(0)
}
.hero .hero-item .cover {
    -o-object-fit: cover;
    object-fit: cover;
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%
}
.hero .hero-item .bottom-shadow {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 80px;
    background-image: linear-gradient(to bottom, rgba(0, 0, 0, 0), rgba(0, 0, 0, .75))
}
.hero .hero-item .captions {
    position: absolute;
    top: 100%;
    left: 15px;
    -webkit-transform: translateY(calc(-100% - 10px));
    transform: translateY(calc(-100% - 10px));
    color: #fff;
    transition: all .4s;
    z-index: 1
}
.hero .hero-item .captions h5 {
    font-size: 12px;
    font-weight: 500
}
.hero .hero-item .captions h3 {
    font-size: 16px;
    font-weight: 700
}
.hero .hero-item .chapter {
    position: absolute;
    top: 0;
    left: 0;
    -webkit-transform: translate(calc(1% + 15px), calc(100% - 10px));
    transform: translate(calc(1% + 15px), calc(100% - 10px));
    white-space: nowrap;
    font-size: 14px;
    font-weight: 500;
    color: #fff;
    padding: 3px 6px 2px;
    border-radius: 5px;
    background-color: #000;
    transition: all .4s;
    z-index: 1
}
