}

/* ========== THEME SWITCH WRAPPER - Independent from ul li button ========== */
body header .top .right ul li.theme-switch-wrapper {
    font-size: 17px;
    height: 44px;
    width: 44px;
    color: #fff;
    border-radius: 150px;
    line-height: 44px;
    text-align: center;
    display: block;
    position: relative;
    margin: 5px 0;
