}

/* Reset ALL inherited button styles inside theme-switch-wrapper */
body header .top .right ul li.theme-switch-wrapper .theme-switch-btn,
body header .top .right ul li.theme-switch-wrapper > button {
    all: unset !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 44px !important;
    height: 44px !important;
    cursor: pointer !important;
}

/* Show img element in normal mode */
