    display: block;
}

/* Community Banner */
.community-banner {
    background-color: rgba(241, 129, 33, 0.8);
    width: 100%;
    border-radius: 10px;
    margin: 10px 0;
    overflow: hidden;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.1);
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 40px;
}

.banner-content {
    display: flex;
    flex: 1 1 0;
    justify-content: space-between;
    align-items: center;
    padding: 5px 10px;
}

.banner-left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.icon-container {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background-color: #5D4037;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
}

.icon-container i {
    color: #FFFFFF;
    font-size: 16px;
}

.banner-text {
    display: flex;
    flex-direction: column;
}

.banner-title {
    font-size: 16px;
    font-weight: bold;
    margin: 0 0 4px 0;
    color: #fff;
    line-height: 1.2;
}

.banner-subtitle {
    font-size: 13px;
    margin: 0;
    color: #fff;
    line-height: 1.3;
    display: none;
}

.banner-right {
    display: flex;
    gap: 10px;
    flex-shrink: 0;
}

.social-button {
    padding: 8px 16px;
    border-radius: 30px;
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 500;
    color: #FFFFFF;
    transition: all 0.3s ease;
    background-color: #5D4037;
}

.social-button:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(93, 64, 55, 0.25);
}

.facebook {
    background: linear-gradient(135deg, #4267B2 0%, #365899 100%);
}

.discord {
    background: linear-gradient(135deg, #7289DA 0%, #7289DA 100%);
}

.telegram {
    background: linear-gradient(135deg, #0088CC 0%, #0088CC 100%);
}

/* Banner Divider */
.banner-divider {
    width: 1px;
    height: 40px;
    background: rgba(93, 64, 55, 0.15);
    align-self: center;
    margin: 0;
    flex-shrink: 0;
}

/* Contact Content (inside community-banner) */
.contact-content {
    display: flex;
    flex: 1 1 0;
    justify-content: space-between;
    align-items: center;
    padding: 5px 10px;
}

.contact-left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.contact-icon {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background-color: #5D4037;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
}

.contact-icon i {
    color: #FFFFFF;
    font-size: 16px;
}

.contact-text {
    display: flex;
    flex-direction: column;
}

.contact-title {
    font-size: 16px;
    font-weight: bold;
    margin: 0 0 4px 0;
    color: #fff;
}

.contact-desc {
    font-size: 13px;
    margin: 0;
    color: #fff;
}

.contact-button {
    padding: 8px 10px;
    border-radius: 30px;
    background-color: #5D4037;
    color: #FFFFFF;
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 500;
    transition: all 0.3s ease;
}

.contact-button:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(93, 64, 55, 0.25);
}

/* Mobile responsive */
@media (max-width: 768px) {
    .community-banner {
        margin: 8px 0 0 0;
        display: flex;
        align-items: stretch;
        gap: 0px;
    }

    /* Each section = 1 row: title | buttons | icon */
    .banner-content,
    .contact-content {
        flex: 1;
        flex-direction: row;
        align-items: center;
        padding: 0 8px;
        gap: 6px;
        min-height: 44px;
    }

    .banner-subtitle,
    .contact-desc {
        display: none;
    }

    .banner-left,
    .contact-left {
        flex: 1;
        flex-direction: row;
        align-items: center;
        gap: 0;
        min-width: 0;
    }

    /* Hide circle icon container */
    .icon-container,
    .contact-icon {
        display: none;
    }

    .banner-title,
    .contact-title {
        font-size: 10px;
        font-weight: 700;
        margin: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .banner-right {
        gap: 5px;
        flex-shrink: 0;
    }

    /* Icon-only circular buttons */
    .social-button,
    .contact-button {
        font-size: 0;
        width: 25px;
        height: 25px;
        padding: 0;
        border-radius: 50%;
        justify-content: center;
        align-items: center;
        gap: 0;
        flex-shrink: 0;
    }

    .social-button i,
    .contact-button i {
        font-size: 13px;
    }

    .banner-divider {
        width: 1px;
        height: 30px;
        align-self: center;
        margin: 0;
    }
}

