}

/* Community Banner */
.community-banner {
    background-color: rgba(241, 129, 33, 0.8);
    width: 100%;
    border-radius: 10px;
    margin: 10px 0;
    overflow: hidden;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.1);
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 40px;
}

.banner-content {
    display: flex;
    flex: 1 1 0;
    justify-content: space-between;
    align-items: center;
    padding: 5px 10px;
}

.banner-left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.icon-container {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background-color: #5D4037;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
}

.icon-container i {
    color: #FFFFFF;
    font-size: 16px;
}

.banner-text {
    display: flex;
    flex-direction: column;
}

.banner-title {
    font-size: 16px;
    font-weight: bold;
    margin: 0 0 4px 0;
    color: #fff;
    line-height: 1.2;
}

.banner-subtitle {
    font-size: 13px;
    margin: 0;
    color: #fff;
    line-height: 1.3;
    display: none;
}

.banner-right {
    display: flex;
    gap: 10px;
    flex-shrink: 0;
}

.social-button {
    padding: 8px 16px;
    border-radius: 30px;
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 500;
    color: #FFFFFF;
    transition: all 0.3s ease;
    background-color: #5D4037;
}

.social-button:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(93, 64, 55, 0.25);
}

.facebook {
    background: linear-gradient(135deg, #4267B2 0%, #365899 100%);
}

.discord {
    background: linear-gradient(135deg, #7289DA 0%, #7289DA 100%);
}

.telegram {
    background: linear-gradient(135deg, #0088CC 0%, #0088CC 100%);
}

