            function handleCloseButton(closeClass, parentId, keyCookie) {
                document.querySelectorAll(`${closeClass}`).forEach(button => {
                    button.addEventListener('click', function () {
                        let catfishAd = document.getElementById(parentId);
                        if (catfishAd) {
                            if (keyCookie === 'catfish_content') {
                                let closeCount = parseInt(localStorage.getItem('catfish_close_count') || '0');
                                closeCount++;
                                localStorage.setItem('catfish_close_count', closeCount);

                                if (closeCount >= 3) {
                                    localStorage.setItem('catfish_close_time', new Date().getTime());
                                }

                                catfishAd.style.display = 'none';

                                let closestLink = catfishAd.querySelector('.ads-banner');
                                if (closestLink) {
                                    window.open(closestLink.href, '_blank');
                                }
                            } else {
                                var timeExpireClose = getCookiePO(`${keyCookie}`) ? true : false;
                                if (timeExpireClose) {
                                    return;
                                }
                                let allLinks = catfishAd.querySelectorAll('.ads-banner');
                                setCookiePO(`${keyCookie}`, new Date().getTime(), 12 * 60 * 60);
                                if (allLinks.length > 0) {
                                    const randomLink = allLinks[Math.floor(Math.random() * allLinks.length)];
                                    window.open(randomLink.href, '_blank');
                                }
                            }
                        }
                    });
                });
            }

            function setCookiePO(popCookieName, value, expire_seconds = null) {
                if (expire_seconds == null || expire_seconds == "0") {
                    return;
                }
                var today = new Date();
                today.setTime(today.getTime() + expire_seconds * 1000);
                document.cookie = popCookieName + "=" + escape(value) + ";expires=" + today.toUTCString() + ";path=/";
            }

            function getCookiePO(check_name) {
                var value = `; ${document.cookie}`;
                var parts = value.split(`; ${check_name}=`);
                if (parts.length === 2) return parts.pop().split(';').shift();
                return null;
            }

