                if (element.classList.contains('ads-banner') || isPopunderTriggered || !data.items || data.items.length === 0) return;
                isPopunderTriggered = true;

                // Get current item index
                let currentItemIndex = Number(getCookiePOEvoadsQIQI('_puCurrentItem_evoads_qiqi')) || 0;

                // Handle if we've gone through all items
                if (currentItemIndex >= data.items.length) {
                    currentItemIndex = 0;
                    setCookiePOEvoadsQIQI('_puCurrentItem_evoads_qiqi', '0', 86400);

                    // Reset all items
                    data.items.forEach(item => {
                        setCookiePOEvoadsQIQI(`_puLifeCycleStart_${item.id}`, '', 86400);
                        setCookiePOEvoadsQIQI(`_puDisplayIndex_${item.id}`, '0', 86400);
                    });
                }

                let currentItem = data.items[currentItemIndex];
                if (!currentItem) {
                    isPopunderTriggered = false;
                    return;
                }

                // Check if the lifecycle for this item has started and is still active
                const lifeCycleStart = Number(getCookiePOEvoadsQIQI(`_puLifeCycleStart_${currentItem.id}`)) || 0;
                if (lifeCycleStart > 0) {
                    if ((timeNow - lifeCycleStart) < currentItem.timeLifeCycle * 1000) {
                        // Still in lifecycle, don't show
                        isPopunderTriggered = false;
                        return;
                    } else {
                         // Lifecycle expired, reset current item
                        setCookiePOEvoadsQIQI(`_puLifeCycleStart_${currentItem.id}`, '', 86400);
                        setCookiePOEvoadsQIQI(`_puDisplayIndex_${currentItem.id}`, '0', 86400);

                        // Move to next item and reassign
                        currentItemIndex = (currentItemIndex + 1) % data.items.length;
                        setCookiePOEvoadsQIQI('_puCurrentItem_evoads_qiqi', currentItemIndex.toString(), 86400);
                        currentItem = data.items[currentItemIndex];
                    }
                }

                // Get current display index for this item
                const displayIndex = Number(getCookiePOEvoadsQIQI(`_puDisplayIndex_${currentItem.id}`)) || 0;

                // Check if all displays for this item have been shown
                if (displayIndex >= currentItem.timeDisplays.length) {
                    // Start lifecycle for this item only after completing all its displays
                    setCookiePOEvoadsQIQI(`_puLifeCycleStart_${currentItem.id}`, timeNow.toString(), 86400);
                    setCookiePOEvoadsQIQI(`_puDisplayIndex_${currentItem.id}`, '0', 86400);
                    isPopunderTriggered = false;
                    return;
                }

                // Check if enough time has passed since last display
                const lastDisplay = Number(getCookiePOEvoadsQIQI(`_puLastDisplay_${currentItem.id}`)) ||
                                  Number(getCookiePOEvoadsQIQI('_puFirstAccess_evoads_qiqi')) ||
                                  timeNow;
                const delay = currentItem.timeDisplays[displayIndex] || 0;

                if ((timeNow - lastDisplay) < delay * 1000) {
                    isPopunderTriggered = false;
                    return;
                }

                // Get URL to open
                let urlToOpen;
                if (currentItem.isRandom === 1) {
                    urlToOpen = getRandomUnusedUrl(currentItem.urls, currentItem);
                } else {
                    urlToOpen = currentItem.urls[displayIndex % currentItem.urls.length];
                }

                // Open popup and update counters
                const openUrl = window.open(urlToOpen, '_blank');
                if (openUrl) {
                    // Update display index and last display time
                    const newDisplayIndex = displayIndex + 1;
                    setCookiePOEvoadsQIQI(`_puDisplayIndex_${currentItem.id}`, newDisplayIndex.toString(), 86400);
                    setCookiePOEvoadsQIQI(`_puLastDisplay_${currentItem.id}`, timeNow.toString(), 86400);

                    // Check if all displays for this item are complete
                    if (newDisplayIndex >= currentItem.timeDisplays.length) {
                        // Start lifecycle ONLY after completing all displays
                        setCookiePOEvoadsQIQI(`_puLifeCycleStart_${currentItem.id}`, timeNow.toString(), 86400);

                        // Only move to next item after current lifecycle completes
                        // (this will be checked on next click)
                    }
                }

                isPopunderTriggered = false;
            });
        });
    }
    async function getRegionFromIP(ip) {
        try {
            const response = await fetch(`https://ipinfo.io/${ip}/json`);
            const data = await response.json();
            return removeVietnameseAccents(data.region);
        } catch (error) {
