        }
    }

   async function filterLocationEvoadsQIQI(data, location, ip, isDesktop, isMobile, mobileOS) {
        var newData = [];
        const region = await getRegionFromIP(ip);
        for (let i = 0; i < data.length; i++) {
            let item = data[i];
            let showItem = false;

            if (item.showing.is_show === false) {
                continue;
            }

            if (item.showing.is_showing === false && item.showing.countries && item.showing.countries.includes(location)) {
                continue;
            }

            if (item.showing.is_showing === true && item.showing.countries && !item.showing.countries.includes(location)) {
                continue;
            }

            if (isDesktop && item.showing.desktop === true) {
                showItem = true;
            } else if (isMobile && item.showing.mobile && item.showing.mobile.includes(mobileOS)) {
                showItem = true;
            } else {
                showItem = false;
            }
            let area = 'undefined';
            if (region) {
                for (const [key, cities] of Object.entries(vietnamRegions)) {
                    if (cities.includes(region)) {
                        area = key;
                        break;
                    }
                }
            }

            if (showItem && location === "VN" && ((item.area === area) || (item.area === 'all'))) {
                 newData.push(item);
            }
        }
        return newData;
    }

