    .qn-manhwa { background: linear-gradient(135deg, #43a047, #2e7d32); }
    .qn-manhua { background: linear-gradient(135deg, #fb8c00, #e65100); }
}

.home-intro-section {
    margin: 20px 0;
    padding: 0 10px;
}
.home-intro-content {
    background: var(--bg-content, #fff);
    border-radius: 8px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.intro-text {
    line-height: 1.8;
    color: var(--text-color, #333);
    font-size: 15px;
}
.intro-text.collapsed {
    max-height: 280px;
    overflow: hidden;
    position: relative;
}
.intro-text.collapsed::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 80px;
    background: linear-gradient(transparent, var(--bg-content, #fff));
}
.intro-text h1 {
    font-size: 24px;
    text-align: center;
    margin-bottom: 12px;
}
.intro-text h2 {
    margin: 20px 0 10px;
    float: none!important;
}
.intro-text h3 {
    color: #f18121;
    margin: 15px 0 8px;
    font-size: 18px;
}
.intro-text p {
    margin-bottom: 12px;
}
.intro-text ul {
    margin: 10px 0 15px 20px;
    list-style-type: disc;

}
.intro-text ul li {
    margin-bottom: 8px;
}
.intro-text a {
    font-weight: 700;
    text-decoration: underline!important;
}
.intro-quote {
    background: var(--bg-highlight, #f0f7ff);
    border-left: 4px solid #f18121;
    padding: 15px 20px;
    margin: 15px 0;
    font-style: italic;
    border-radius: 0 8px 8px 0;
}
.intro-quote p {
    margin-bottom: 10px;
}
.intro-quote p:last-child {
    margin-bottom: 0;
}
.btn-view-intro {
    display: block;
    width: 100%;
    max-width: 200px;
    margin: 15px auto 0;
    padding: 10px 20px;
    background: transparent;
    color: #f18121;
    border: none;
    cursor: pointer;
    font-size: 14px;
    font-weight: 700;
    transition: all 0.3s ease;
    text-decoration: underline;
}
.btn-view-intro i {
    margin-left: 8px;
    transition: transform 0.3s ease;
}
.btn-view-intro.expanded i {
    transform: rotate(180deg);
}
