}

/* Contact Section - Dark Mode */
body.dark .contact-title {
    color: #e2e8f0;
}

body.dark .contact-desc {
    color: #e2e8f0;
}

body.dark .contact-icon {
    background-color: #5D4037;
}

body.dark .contact-icon i {
    color: #FFFFFF;
}

body.dark .social-button.facebook {
    background-color: #5D4037;
}

body.dark .social-button.discord {
    background-color: #5D4037;
}

body.dark .contact-button.telegram {
