    font-weight: bold;
    margin: 0 0 4px 0;
    color: #fff;
    line-height: 1.2;
}

.banner-subtitle {
    font-size: 13px;
    margin: 0;
    color: #fff;
    line-height: 1.3;
    display: none;
}

.banner-right {
    display: flex;
    gap: 10px;
    flex-shrink: 0;
}

.social-button {
    padding: 8px 16px;
    border-radius: 30px;
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 500;
    color: #FFFFFF;
    transition: all 0.3s ease;
    background-color: #5D4037;
}

.social-button:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(93, 64, 55, 0.25);
}

.facebook {
    background: linear-gradient(135deg, #4267B2 0%, #365899 100%);
}

.discord {
    background: linear-gradient(135deg, #7289DA 0%, #7289DA 100%);
}

.telegram {
    background: linear-gradient(135deg, #0088CC 0%, #0088CC 100%);
}

/* Banner Divider */
.banner-divider {
    width: 1px;
    height: 40px;
    background: rgba(93, 64, 55, 0.15);
    align-self: center;
    margin: 0;
    flex-shrink: 0;
}

/* Contact Content (inside community-banner) */
.contact-content {
    display: flex;
    flex: 1 1 0;
    justify-content: space-between;
    align-items: center;
    padding: 5px 10px;
}

.contact-left {
    display: flex;
    align-items: center;
    gap: 12px;
}

.contact-icon {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background-color: #5D4037;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
}

.contact-icon i {
    color: #FFFFFF;
    font-size: 16px;
}

.contact-text {
    display: flex;
    flex-direction: column;
}

.contact-title {
    font-size: 16px;
    font-weight: bold;
    margin: 0 0 4px 0;
    color: #fff;
}

.contact-desc {
    font-size: 13px;
    margin: 0;
    color: #fff;
}

.contact-button {
    padding: 8px 10px;
    border-radius: 30px;
    background-color: #5D4037;
    color: #FFFFFF;
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 500;
    transition: all 0.3s ease;
}

.contact-button:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(93, 64, 55, 0.25);
}

/* Mobile responsive */
@media (max-width: 768px) {
    .community-banner {
        margin: 8px 0 0 0;
        display: flex;
        align-items: stretch;
        gap: 0px;
    }

    /* Each section = 1 row: title | buttons | icon */
    .banner-content,
    .contact-content {
        flex: 1;
        flex-direction: row;
        align-items: center;
        padding: 0 8px;
        gap: 6px;
        min-height: 44px;
    }

    .banner-subtitle,
    .contact-desc {
        display: none;
    }

    .banner-left,
    .contact-left {
        flex: 1;
        flex-direction: row;
        align-items: center;
        gap: 0;
        min-width: 0;
    }

    /* Hide circle icon container */
    .icon-container,
    .contact-icon {
        display: none;
    }

    .banner-title,
    .contact-title {
        font-size: 10px;
        font-weight: 700;
        margin: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .banner-right {
        gap: 5px;
        flex-shrink: 0;
    }

    /* Icon-only circular buttons */
    .social-button,
    .contact-button {
        font-size: 0;
        width: 25px;
        height: 25px;
        padding: 0;
        border-radius: 50%;
        justify-content: center;
        align-items: center;
        gap: 0;
        flex-shrink: 0;
    }

    .social-button i,
    .contact-button i {
        font-size: 13px;
    }

    .banner-divider {
        width: 1px;
        height: 30px;
        align-self: center;
        margin: 0;
    }
}

/* Google Preferred Source button (inside community-banner) */
.gg-preferred-source {
    display: inline-flex;
    align-self: flex-start;
    align-items: center;
    gap: 8px;
    max-width: 100%;
    margin: 0;
    padding: 5px 14px;
    border: 1px solid #b9bdc1;
    border-radius: 16px;
    background: #fff;
    color: #3c4043 !important;
    -webkit-text-fill-color: #3c4043 !important;
    font-size: 13px;
    font-weight: 500;
    line-height: 1.3;
    text-decoration: none;
    transition: background .15s ease, border-color .15s ease;
}

.gg-preferred-source:hover {
    background: #f1f3f4;
    border-color: #9aa0a6;
}

.gg-preferred-source:focus-visible {
    outline: 2px solid #1a73e8;
    outline-offset: 2px;
}

.gg-preferred-source img {
    display: block;
    width: 18px;
    height: 18px;
    flex: 0 0 18px;
}

@media (max-width: 768px) {
    .community-banner .banner-content {
        padding-top: 8px;
        padding-bottom: 8px;
    }

    .gg-preferred-source .gg-ps-line {
        display: block;
    }
}

@media (max-width: 575.98px) {
    .gg-preferred-source {
        padding: 4px 10px;
        gap: 6px;
        font-size: 12px;
    }
}

/* Quick Nav — mobile only */
.quick-nav {
    display: none;
}

@media (max-width: 768px) {
    .quick-nav {
        display: flex;
        gap: 6px;
        margin: 6px 0;
    }

    .quick-nav-btn {
        flex: 1;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 4px;
        padding: 8px 4px;
        border-radius: 8px;
        text-decoration: none;
        font-size: 14px;
        font-weight: 600;
        color: #fff;
        line-height: 1.2;
    }

    .quick-nav-btn i {
        font-size: 16px;
    }

    .qn-top    { background: linear-gradient(135deg, #e53935, #c62828); }
    .qn-manga  { background: linear-gradient(135deg, #1e88e5, #1565c0); }
    .qn-manhwa { background: linear-gradient(135deg, #43a047, #2e7d32); }
    .qn-manhua { background: linear-gradient(135deg, #fb8c00, #e65100); }
}

.home-intro-section {
    margin: 20px 0;
    padding: 0 10px;
}
.home-intro-content {
    background: var(--bg-content, #fff);
    border-radius: 8px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.intro-text {
    line-height: 1.8;
    color: var(--text-color, #333);
    font-size: 15px;
}
.intro-text.collapsed {
    max-height: 280px;
    overflow: hidden;
    position: relative;
}
.intro-text.collapsed::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 80px;
    background: linear-gradient(transparent, var(--bg-content, #fff));
}
.intro-text h1 {
    font-size: 24px;
    text-align: center;
    margin-bottom: 12px;
}
.intro-text h2 {
    margin: 20px 0 10px;
