}
body.dark .btn-avatar {
  background-color: #3a3b3c;
  color: #e4e6eb;
  border: 1px solid #4a4b4c;
}
body.dark .btn-avatar:hover {
  background-color: #4a4b4c;
}
body.dark .form-change-pass {
  color: #e4e6eb;
}
body.dark .user-field label {
  color: #e4e6eb;
}

/* Dark theme - user menu sidebar */
body.dark .user-menu-custom {
  background-color: #3a3b3c;
}
body.dark .user-menu-custom .nav-user {
  border-color: transparent;
  background-color: #3a3b3c;
}
body.dark .user-menu-custom .nav-user li a {
  color: #b0b3b8!important;
  border-color: transparent;
}
body.dark .user-menu-custom .nav-user li a.is-active {
  color: #f18121!important;
}

