                        setTimeout(function () {
                            closeElement.style.display = "block";
                        }, countdown);

                    }, timeAccessPrevious + timeDelay * 1000 - timeNowMillisecond);
                    setCookiePO(`_${popupId}_timeDelay`, null, 0);
                }
                break;
            }
        }
    }

    function setCookiePO(popCookieName, value, expire_seconds = null) {
        if (expire_seconds == null || expire_seconds == "0") {
            return;
        }
        var today = new Date();
        today.setTime(today.getTime() + expire_seconds * 1000);
        document.cookie = popCookieName + "=" + escape(value) + ";expires=" + today.toUTCString() + ";path=/";
    }

    function getCookiePO(check_name) {
        var value = `; ${document.cookie}`;
        var parts = value.split(`; ${check_name}=`);
        if (parts.length === 2) return parts.pop().split(';').shift();
        return null;
    }

    function popUpSetting(popups) {
        currentPopupIndex = getCookiePO('_popup_index') ? parseInt(getCookiePO('_popup_index')) : 0;
        popups.forEach((popup) => {
            var popView = `
                            <div id="${popup.id}" time-click-close=${popup.timeClickClose} time-click-image-to-hide=${popup.timeClickImageToHidePopup} style="display:none;position:fixed;top:50%;left:50%;transform:translate(-50%, -50%);background-color:rgba(0, 0, 0, 0.5);width:100vw;height:100vh;z-index:99999;justify-content:center;">
                                <div style="text-align:center;margin:auto;display:flex;">
                                    <div style="text-align:center;height:fit-content;align-content:center;width:fit-content;position:relative;">
                                        <a class="ads-banner" rel="nofollow" id="url-${popup.id}" target="_blank" href="${popup.urlPopUnder}">
                                            <img class="ads-banner" id="img-${popup.id}" style="max-width:500px" src="${poMobile ? popup.imageUrl.mobile : popup.imageUrl.desktop}" />
                                        </a>
                                        <div class="popup-icon-close" style="position:absolute;width:50px;right:-20px;top:-20px;height:50px;z-index:9999999999;cursor:pointer;">
                                            <div id="close-${popup.id}" url-close="${popup.urlPopUnderClose}" style="color:#000;float:right;font-size:1.5rem;font-weight:bold;display:flex;justify-content:center;align-items:center;width:30px;height:30px;border-radius:50%;background-color:#959595;font-size:24px;display:none;">×</div>
                                        </div>
                                    </div>
                                </div>
                            </div>`;
            document.body.insertAdjacentHTML('beforeend', popView);
            var popupId = popup.id;
            var popupElement = document.getElementById(popupId);
            checkVersionPopup(popupId, popup.version);
            document.getElementById(`close-${popupId}`).addEventListener("click", function () {
                if (popupElement.innerHTML.length) {
                    var timeClickClose = getCookiePO(`_${popupId}_timeClickClose`) ? Number(getCookiePO(`_${popupId}_timeClickClose`)) : 1;
                    var maxTimeClickClose = popupElement.getAttribute('time-click-close');
                    var conditionToPass = (!popup.hidePopupWhenUserClickImage && !maxTimeClickClose) || (maxTimeClickClose && timeClickClose >= Number(maxTimeClickClose));

                    popupElement.style.display = "none";

                    setCookiePO(`_${popupId}_timeClickClose`, timeClickClose + 1, 24 * 60 * 60);
                    var urlRedirect = this.getAttribute('url-close');
                    if (urlRedirect) {
                        window.open(urlRedirect, '_blank');
                    }

                    var timeIndex = +(getCookiePO(`_${popupId}_timeShow`) ?? 0) + 1;
                    var timeNow = (new Date()).getTime();
                    if (conditionToPass) {
                        setCookiePO(`_${popupId}_timePrevious`, timeNow, 24 * 60 * 60);
                        setCookiePO(`_${popupId}_timeShow`, timeIndex, 24 * 60 * 60);
                        setCookiePO(`_${popupId}_timeClickClose`, null, 0);

                        if (timeIndex == popup.timeDisplays.length) {
                            resetStatusPopup(popupId);
                            currentPopupIndex = getCookiePO('_popup_index') ? parseInt(getCookiePO('_popup_index')) : 0;
                            setCookiePO(`_${popupId}_timeDelay`, timeNow + popup.timeLifeCycle * 1000, 24 * 60 * 60);
                            setCookiePO('_popup_index', currentPopupIndex + 1, 24 * 60 * 60);
                        } else {
                            setCookiePO('_popup_index', currentPopupIndex + 1, 24 * 60 * 60);
                        }
                    }
                }
            });
            if (popup.hidePopupWhenUserClickImage) {
                if (document.getElementById(`url-${popupId}`)) {
                    document.getElementById(`url-${popupId}`).addEventListener("click", function (event) {
                        event.preventDefault();
                        if (popupElement.innerHTML.length) {
                            var timeClickImage = getCookiePO(`_${popupId}_timeClickImage`) ? Number(getCookiePO(`_${popupId}_timeClickImage`)) : 1;
                            var timeClickImageToHidePopup = popupElement.getAttribute('time-click-image-to-hide');
                            var conditionToPass = timeClickImageToHidePopup && timeClickImage >= Number(timeClickImageToHidePopup);

                            popupElement.style.display = "none";

                            setCookiePO(`_${popupId}_timeClickImage`, timeClickImage + 1, 24 * 60 * 60);
                            var urlRedirect = this.getAttribute('href');
                            if (urlRedirect) {
                                window.open(urlRedirect, '_blank');
                            }

                            var timeIndex = +getCookiePO(`_${popupId}_timeShow`) + 1;
                            var timeNow = (new Date()).getTime();
                            if (conditionToPass) {
                                setCookiePO(`_${popupId}_timePrevious`, timeNow, 24 * 60 * 60);
                                setCookiePO(`_${popupId}_timeShow`, timeIndex, 24 * 60 * 60);
                                setCookiePO(`_${popupId}_timeClickImage`, null, 0);

                                if (timeIndex == popup.timeDisplays.length) {
                                    resetStatusPopup(popupId);
                                    currentPopupIndex = getCookiePO('_popup_index') ? parseInt(getCookiePO('_popup_index')) : 0;
                                    setCookiePO(`_${popupId}_timeDelay`, timeNow + popup.timeLifeCycle * 1000, 24 * 60 * 60);
                                    setCookiePO('_popup_index', currentPopupIndex + 1, 24 * 60 * 60);
                                } else {
                                    setCookiePO('_popup_index', currentPopupIndex + 1, 24 * 60 * 60);
                                }
                            }
                        }
                    });
                }
            }
        });
        firstTimeAccessPopup(popups);
    }

    function checkVersionPopup(popupId, ver) {
        var currentVer = getCookiePO(`_${popupId}_version`);
        if (currentVer == null || currentVer != ver) {
            resetStatusPopup(popupId);
            setCookiePO(`_${popupId}_version`, ver, 24 * 60 * 60);
        }
    }

    function resetStatusPopup(popupId) {
        setCookiePO(`_${popupId}_timePrevious`, null, 0);
        setCookiePO(`_${popupId}_timeShow`, null, 0);
        setCookiePO(`_${popupId}_timeClickClose`, null, 0);
        setCookiePO(`_${popupId}_timeClickImage`, null, 0);
        setCookiePO(`_${popupId}_timeDelay`, null, 0);
    }

    function getRandomUrl(arrIndex, arrUrls) {
        var arrRandom = [];
        arrIndex.forEach(function (element) {
            arrRandom.push(arrUrls[element]);
        });
        var randomValue = arrRandom[Math.floor(Math.random() * arrRandom.length)];
        return randomValue;
