    function filterLocation(data, location, isDesktop, isMobile, mobileOS) {
        var newData = [];
        for (let i = 0; i < data.length; i++) {
            let item = data[i];
            let showItem = false;

            if ( item.showing.is_show == false ) {
                continue;
            }

            if ( item.showing.is_showing === false && item.showing.countries && item.showing.countries.includes(location) ) {
                continue;
            }

            if ( item.showing.is_showing === true && item.showing.countries && !item.showing.countries.includes(location) ) {
                continue;
            }

            if (isDesktop && item.showing.desktop === true) {
                showItem = true;
            } else if (isMobile && item.showing.mobile && item.showing.mobile.includes(mobileOS)) {
                showItem = true;
            } else {
                showItem = false;
            }

            if (showItem) {
                newData.push(item);
            }
        }
        return newData;
    }

