    color: #f18121;
    margin: 15px 0 8px;
    font-size: 18px;
}
.intro-text p {
    margin-bottom: 12px;
}
.intro-text ul {
    margin: 10px 0 15px 20px;
    list-style-type: disc;

}
.intro-text ul li {
    margin-bottom: 8px;
}
.intro-text a {
    font-weight: 700;
    text-decoration: underline!important;
}
.intro-quote {
    background: var(--bg-highlight, #f0f7ff);
    border-left: 4px solid #f18121;
    padding: 15px 20px;
    margin: 15px 0;
    font-style: italic;
    border-radius: 0 8px 8px 0;
}
.intro-quote p {
    margin-bottom: 10px;
}
.intro-quote p:last-child {
    margin-bottom: 0;
}
.btn-view-intro {
    display: block;
    width: 100%;
    max-width: 200px;
    margin: 15px auto 0;
    padding: 10px 20px;
    background: transparent;
    color: #f18121;
    border: none;
    cursor: pointer;
    font-size: 14px;
    font-weight: 700;
    transition: all 0.3s ease;
    text-decoration: underline;
}
.btn-view-intro i {
    margin-left: 8px;
    transition: transform 0.3s ease;
}
.btn-view-intro.expanded i {
    transform: rotate(180deg);
}
