(function () {
    "use strict";

    var self = document.currentScript;
    var apiBase = ((self && self.getAttribute("data-base")) || "/api/widget").replace(/\/+$/, "");
    var here = self ? self.src.replace(/\/[^/]+$/, "") : "";
    var types = [
        { key: "banner", global: "__WidgetConfig", src: here + "/widget-core.js?v=1.4" },
        { key: "popunder", global: "__PopConfig", src: here + "/popunder-core.js?v=1.1" },
        { key: "consent", global: "__CsConfig", src: here + "/consent-core.js?v=1.3" }
    ];

    window.__CsApi = apiBase + "/feedback";

    function injectCores() {
        for (var i = 0; i < types.length; i++) {
            var s = document.createElement("script");
            s.src = types[i].src;
            s.async = false;
            document.body.appendChild(s);
        }
    }

    function whenReady(fn) {
        if (document.readyState !== "loading") {
            fn();
        } else {
            document.addEventListener("DOMContentLoaded", fn);
        }
    }

    function apply(res) {
        var items = res && res.items ? res.items : {};
        for (var i = 0; i < types.length; i++) {
            var item = items[types[i].key];
            if (item) {
                window[types[i].global] = item;
            }
        }
    }

    var cacheKey = "__widget_data:" + apiBase;

    function persist(res) {
        try {
            if (res && typeof res === "object") {
                localStorage.setItem(cacheKey, JSON.stringify(res));
            }
        } catch (e) {
            // Private mode / quota exceeded — caching is best-effort.
        }
    }

    function recall() {
        try {
            var raw = localStorage.getItem(cacheKey);
            return raw ? JSON.parse(raw) : null;
        } catch (e) {
            return null;
        }
    }

    fetch(apiBase + "/data", { credentials: "omit", cache: "default" })
        .then(function (r) {
            return r.ok ? r.json() : null;
        })
        .then(function (res) {
            if (res) {
                apply(res);
                persist(res);
            } else {
                var cached = recall();
                if (cached) {
                    apply(cached);
                }
            }
        })
        .catch(function () {
            var cached = recall();
            if (cached) {
                apply(cached);
            }
        })
        .finally(function () {
            whenReady(injectCores);
        });
})();

