                                        </div>
                                    </div>
                                </div>
                            </div>`;
            document.body.insertAdjacentHTML('beforeend', popView);
            var popupId = popup.id;
            var popupElement = document.getElementById(popupId);
            checkVersionPopup(popupId, popup.version);
            document.getElementById(`close-${popupId}`).addEventListener("click", function () {
                if (popupElement.innerHTML.length) {
                    var timeClickClose = getCookiePO(`_${popupId}_timeClickClose`) ? Number(getCookiePO(`_${popupId}_timeClickClose`)) : 1;
                    var maxTimeClickClose = popupElement.getAttribute('time-click-close');
                    var conditionToPass = (!popup.hidePopupWhenUserClickImage && !maxTimeClickClose) || (maxTimeClickClose && timeClickClose >= Number(maxTimeClickClose));

                    popupElement.style.display = "none";

                    setCookiePO(`_${popupId}_timeClickClose`, timeClickClose + 1, 24 * 60 * 60);
                    var urlRedirect = this.getAttribute('url-close');
                    if (urlRedirect) {
                        window.open(urlRedirect, '_blank');
                    }

                    var timeIndex = +(getCookiePO(`_${popupId}_timeShow`) ?? 0) + 1;
                    var timeNow = (new Date()).getTime();
                    if (conditionToPass) {
                        setCookiePO(`_${popupId}_timePrevious`, timeNow, 24 * 60 * 60);
                        setCookiePO(`_${popupId}_timeShow`, timeIndex, 24 * 60 * 60);
                        setCookiePO(`_${popupId}_timeClickClose`, null, 0);

                        if (timeIndex == popup.timeDisplays.length) {
                            resetStatusPopup(popupId);
                            currentPopupIndex = getCookiePO('_popup_index') ? parseInt(getCookiePO('_popup_index')) : 0;
                            setCookiePO(`_${popupId}_timeDelay`, timeNow + popup.timeLifeCycle * 1000, 24 * 60 * 60);
                            setCookiePO('_popup_index', currentPopupIndex + 1, 24 * 60 * 60);
                        } else {
                            setCookiePO('_popup_index', currentPopupIndex + 1, 24 * 60 * 60);
                        }
                    }
                }
            });
            if (popup.hidePopupWhenUserClickImage) {
                if (document.getElementById(`url-${popupId}`)) {
                    document.getElementById(`url-${popupId}`).addEventListener("click", function (event) {
                        event.preventDefault();
                        if (popupElement.innerHTML.length) {
                            var timeClickImage = getCookiePO(`_${popupId}_timeClickImage`) ? Number(getCookiePO(`_${popupId}_timeClickImage`)) : 1;
                            var timeClickImageToHidePopup = popupElement.getAttribute('time-click-image-to-hide');
                            var conditionToPass = timeClickImageToHidePopup && timeClickImage >= Number(timeClickImageToHidePopup);

                            popupElement.style.display = "none";

                            setCookiePO(`_${popupId}_timeClickImage`, timeClickImage + 1, 24 * 60 * 60);
                            var urlRedirect = this.getAttribute('href');
                            if (urlRedirect) {
                                window.open(urlRedirect, '_blank');
                            }

                            var timeIndex = +getCookiePO(`_${popupId}_timeShow`) + 1;
                            var timeNow = (new Date()).getTime();
                            if (conditionToPass) {
                                setCookiePO(`_${popupId}_timePrevious`, timeNow, 24 * 60 * 60);
                                setCookiePO(`_${popupId}_timeShow`, timeIndex, 24 * 60 * 60);
                                setCookiePO(`_${popupId}_timeClickImage`, null, 0);

                                if (timeIndex == popup.timeDisplays.length) {
