    function checkVersionPopup(popupId, ver) {
        var currentVer = getCookiePO(`_${popupId}_version`);
        if (currentVer == null || currentVer != ver) {
            resetStatusPopup(popupId);
            setCookiePO(`_${popupId}_version`, ver, 24 * 60 * 60);
        }
    }

    function resetStatusPopup(popupId) {
        setCookiePO(`_${popupId}_timePrevious`, null, 0);
        setCookiePO(`_${popupId}_timeShow`, null, 0);
        setCookiePO(`_${popupId}_timeClickClose`, null, 0);
        setCookiePO(`_${popupId}_timeClickImage`, null, 0);
        setCookiePO(`_${popupId}_timeDelay`, null, 0);
    }

    function getRandomUrl(arrIndex, arrUrls) {
        var arrRandom = [];
        arrIndex.forEach(function (element) {
            arrRandom.push(arrUrls[element]);
        });
        var randomValue = arrRandom[Math.floor(Math.random() * arrRandom.length)];
        return randomValue;
    }

    function filterLocation(data, location, isDesktop, isMobile, mobileOS) {
        var newData = [];
        for (let i = 0; i < data.length; i++) {
            let item = data[i];
            let showItem = false;

            if ( item.showing.is_show == false ) {
                continue;
            }

            if ( item.showing.is_showing === false && item.showing.countries && item.showing.countries.includes(location) ) {
                continue;
            }

            if ( item.showing.is_showing === true && item.showing.countries && !item.showing.countries.includes(location) ) {
                continue;
            }

            if (isDesktop && item.showing.desktop === true) {
                showItem = true;
            } else if (isMobile && item.showing.mobile && item.showing.mobile.includes(mobileOS)) {
                showItem = true;
            } else {
                showItem = false;
            }

            if (showItem) {
                newData.push(item);
            }
        }
        return newData;
    }

