        setCookiePO(`_${popupId}_timePrevious`, null, 0);
        setCookiePO(`_${popupId}_timeShow`, null, 0);
        setCookiePO(`_${popupId}_timeClickClose`, null, 0);
        setCookiePO(`_${popupId}_timeClickImage`, null, 0);
