    function checkCookiesValidity(data) {
        const mainCookiesValid = getCookiePOEvoadsQIQI('_puCurrentItem_evoads_qiqi') && 
                                getCookiePOEvoadsQIQI('_puFirstAccess_evoads_qiqi');

        if (!mainCookiesValid) return false;

        // Check item specific cookies
        for (const item of data.items) {
            if (!getCookiePOEvoadsQIQI(`_puDisplayIndex_${item.id}`) || 
                !getCookiePOEvoadsQIQI(`_puLastDisplay_${item.id}`)) {
                return false;
