    function getRandomUnusedUrl(urls, currentItem) {
        let remainingIndices = getCookiePOEvoadsQIQI(`_puRemainingIndices_${currentItem.id}`);
        if (remainingIndices) {
            remainingIndices = decodeURIComponent(remainingIndices).split(',').map(Number);
        } else {
            remainingIndices = [];
        }

        // If no indices are stored or array is empty, initialize it
        if (!Array.isArray(remainingIndices) || remainingIndices.length === 0) {
            remainingIndices = Array.from(urls.keys());
        }
        // Pick a random index from remainingIndices
        const randomIndex = Math.floor(Math.random() * remainingIndices.length);
        const urlIndex = remainingIndices[randomIndex];
        // Remove it from the array
        remainingIndices.splice(randomIndex, 1);

        // If array becomes empty, reinitialize with all indices
        if (remainingIndices.length === 0) {
            remainingIndices = Array.from(urls.keys());
        }

        // Store the updated array in the cookie for 24 hours (86400 seconds)
        setCookiePOEvoadsQIQI(
            `_puRemainingIndices_${currentItem.id}`,
            remainingIndices.join(','),
            86400
        );

        return urls[urlIndex];
    }

